import csv, re, json, os
from datetime import datetime

base="/app/data"
def load(t):
    with open(os.path.join(base,t+".csv")) as f:
        r=csv.DictReader(f)
        return list(r), r.fieldnames

def realdate(v):
    if v is None: return False
    try:
        datetime.strptime(v,"%Y-%m-%d")
        return True
    except: return False

def num(v):
    try: return float(v)
    except: return None

email_re=re.compile(r'^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$')  # simplistic; we'll do custom
def valid_email(v):
    if v is None or v=="": return False
    if v.count("@")!=1: return False
    local,dom=v.split("@")
    if not local or not dom: return False
    parts=dom.split(".")
    if len(parts)<2: return False
    tld=parts[-1]
    if not re.fullmatch(r'[a-z]{2,}',tld): return False
    # domain labels nonempty
    if any(p=="" for p in parts): return False
    return True

cust,cf=load("customers")
ordr,of=load("orders")
oi,qf=load("order_items")
prod,pf=load("products")
ref,rf=load("refunds")
ship,sf=load("shipments")

viol=[]
def add(t,row,col,rule): viol.append({"table":t,"row":row,"column":col,"rule":rule})

# customers
seen=set()
for i,r in enumerate(cust,1):
    if r["id"] in seen: add("customers",i,"id","id")
    seen.add(r["id"])
    if not valid_email(r["email"]): add("customers",i,"email","email")
    if not realdate(r["signup_date"]): add("customers",i,"signup_date","date")
    if r["tier"] not in ("free","pro","enterprise"): add("customers",i,"tier","enum")

cust_ids=set(r["id"] for r in cust)
order_ids=set(r["id"] for r in ordr)
prod_ids=set(r["sku"] for r in prod)

# orders
